// Nodo Code del flujo de check-in: valida el codigo contra las filas leidas de la hoja.
// Entrada: los items de Google Sheets (inscritos del evento) + el codigo del webhook.
const codigo = ($('Webhook check-in').first().json.query.codigo || '').trim();
const filas = $input.all().map((i) => i.json);
const fila = filas.find((f) => String(f.codigo) === codigo);

if (!codigo || !fila) {
  return [{ json: { ok: false, motivo: 'codigo_no_encontrado', mensaje: 'Entrada no encontrada. Pasa por la mesa, lo miramos en la lista.' } }];
}
if (String(fila.estado) !== 'confirmado' && String(fila.estado) !== 'promovido') {
  return [{ json: { ok: false, motivo: 'estado_' + fila.estado, mensaje: 'Esta entrada no está activa (' + fila.estado + '). Pasa por la mesa.' } }];
}
if (String(fila.asistio) === 'true') {
  return [{ json: { ok: false, motivo: 'ya_dentro', mensaje: fila.nombre + ' ya hizo check-in a las ' + fila.hora_checkin + '. Si es un error, mesa.' } }];
}
return [{
  json: {
    ok: true,
    id: fila.id,
    nombre: fila.nombre,
    asistio: true,
    hora_checkin: new Date().toISOString(),
    mensaje: 'Adelante, ' + fila.nombre + ' ✔',
  },
}];

