// Cuenta plazas, detecta duplicados y genera el codigo unico con su QR.
const AFORO_EVENTO = 80; // ajusta al aforo real y a la fila del evento en la hoja
const insc = $('Normalizar inscripción').first().json;
const filas = $input.all().map((i) => i.json).filter((f) => f && f.email);

const duplicado = filas.find((f) => String(f.email).toLowerCase().trim() === insc.email);
const confirmados = filas.filter((f) => ['confirmado', 'promovido'].includes(String(f.estado))).length;
const enEspera = filas.filter((f) => String(f.estado) === 'lista_espera').length;

let codigo;
if (duplicado) {
  codigo = duplicado.codigo; // reenviamos la entrada original: nadie tiene dos
} else {
  const azar = Math.random().toString(36).slice(2, 8).toUpperCase();
  codigo = insc.id_evento + '-' + azar;
}
const qr_url = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' + encodeURIComponent(codigo);

const hayPlaza = duplicado ? ['confirmado', 'promovido'].includes(String(duplicado.estado)) : confirmados < AFORO_EVENTO;

return [{
  json: {
    ...insc,
    duplicado: Boolean(duplicado),
    codigo,
    qr_url,
    plazas_ocupadas: confirmados,
    aforo: AFORO_EVENTO,
    posicion_espera: hayPlaza ? 0 : enEspera + 1,
    hay_plaza: hayPlaza,
    estado: hayPlaza ? 'confirmado' : 'lista_espera',
    asistio: false,
  },
}];
